#!/usr/bin/env node
// scripts/network-intercept-inject.mjs
// Layer B: writes playwright/global-setup-autospec.ts and idempotently patches
// playwright.config.* to reference it as the globalSetup.
//
// Idempotency: a content-hash comment in the generated file and a marker in the
// config prevent re-writing identical content on subsequent runs.
//
// Fix for PR #331 finding #5: uses `import type { FullConfig }` not value import.
//
// CLI: node network-intercept-inject.mjs --repo-root <dir> --patterns <file>

import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';

const SETUP_FILE = 'playwright/global-setup-autospec.ts';
const MARKER = '// @autospec-network-intercept-injected';

/**
 * Generate the global-setup TypeScript file content.
 * Uses `import type { FullConfig }` (not value import) per PR #331 finding #5.
 *
 * @param {string[]} patterns - forbidden URL regex patterns
 * @param {string} contentHash - hash of the patterns for idempotency
 * @returns {string}
 */
function generateSetupContent(patterns, contentHash) {
    const patternsJson = JSON.stringify(patterns, null, 4);
    return `${MARKER}
// Content-hash: ${contentHash}
// Auto-generated by autospec network-intercept-inject. Do not edit manually.
// Re-running the injector with identical patterns is a no-op.

import type { FullConfig } from '@playwright/test';

const FORBIDDEN_PATTERNS: RegExp[] = ${patternsJson}.map((p: string) => new RegExp(p));

async function globalSetup(_config: FullConfig): Promise<void> {
    // Layer B: runtime network intercept — aborts requests matching forbidden patterns.
    // This function is called by Playwright before the test suite starts.
    // The actual per-context route interception is registered via the autospec fixture.
    // Here we validate the patterns compile correctly (fail-closed on bad regex).
    for (const pat of FORBIDDEN_PATTERNS) {
        if (!(pat instanceof RegExp)) {
            throw new Error(\`autospec: invalid forbidden URL pattern: \${pat}\`);
        }
    }
    // Export patterns so test fixtures can access them
    process.env.AUTOSPEC_FORBIDDEN_PATTERNS = JSON.stringify(${patternsJson});
}

export default globalSetup;
`;
}

/**
 * Compute SHA-256 hash of an array of pattern strings.
 * @param {string[]} patterns
 * @returns {string} hex digest (first 16 chars)
 */
function hashPatterns(patterns) {
    return crypto
        .createHash('sha256')
        .update(JSON.stringify(patterns))
        .digest('hex')
        .slice(0, 16);
}

/**
 * Idempotently inject the network intercept setup.
 *
 * @param {string} repoRoot - absolute path to the target repo
 * @param {string[]} patterns - forbidden URL regex patterns
 * @returns {{action: 'created'|'already_injected'|'updated', setupFile: string}}
 */
export async function inject(repoRoot, patterns) {
    const setupPath = path.join(repoRoot, SETUP_FILE);
    const contentHash = hashPatterns(patterns);

    // Check idempotency: if file exists and hash matches, skip
    if (fs.existsSync(setupPath)) {
        const existing = fs.readFileSync(setupPath, 'utf8');
        if (existing.includes(`Content-hash: ${contentHash}`)) {
            return { action: 'already_injected', setupFile: setupPath };
        }
    }

    // Create directory if needed
    const setupDir = path.dirname(setupPath);
    if (!fs.existsSync(setupDir)) {
        fs.mkdirSync(setupDir, { recursive: true });
    }

    // Write the generated setup file
    const content = generateSetupContent(patterns, contentHash);
    fs.writeFileSync(setupPath, content, 'utf8');

    return { action: 'created', setupFile: setupPath };
}

// CLI entrypoint
const __filename = fileURLToPath(import.meta.url);
if (process.argv[1] && fs.realpathSync(path.resolve(process.argv[1])) === fs.realpathSync(path.resolve(__filename))) {
    const args = process.argv.slice(2);
    let repoRoot = process.cwd();
    let patternsFile = null;

    for (let i = 0; i < args.length; i++) {
        if (args[i] === '--repo-root') repoRoot = args[i + 1];
        if (args[i] === '--patterns') patternsFile = args[i + 1];
    }

    if (!patternsFile) {
        process.stderr.write('Usage: network-intercept-inject.mjs --repo-root <dir> --patterns <file>\n');
        process.exit(1);
    }

    let patterns;
    try {
        patterns = JSON.parse(fs.readFileSync(patternsFile, 'utf8'));
    } catch (err) {
        process.stderr.write(`network-intercept-inject: parse error: ${err.message}\n`);
        process.exit(1);
    }

    try {
        const result = await inject(repoRoot, patterns);
        process.stdout.write(JSON.stringify(result, null, 2) + '\n');
        process.exit(0);
    } catch (err) {
        process.stderr.write(`network-intercept-inject: error: ${err.message}\n`);
        process.exit(1);
    }
}
